import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';

export default function Resources() {
  const { selectedCollege, dark, user } = useApp();

  const [data, setData] = useState([]);

  // 🔥 FETCH FIXED
  const fetchResources = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/resources");
      const result = await res.json();

      console.log("API DATA:", result);

      // ✅ FIX: ensure array
      if (Array.isArray(result)) {
        setData(result);
      } else {
        setData([]); // fallback
      }

    } catch (err) {
      console.error(err);
      setData([]);
    }
  };

  useEffect(() => {
    fetchResources();
  }, []);

  const displayCollege =
    user?.role === 'student' && user?.college
      ? user.college
      : selectedCollege;

  const handleDelete = async (id) => {
    try {
      const res = await fetch(`http://localhost:5000/api/resources/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        alert("Deleted");
        fetchResources(); // refresh
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <h1>{displayCollege ? displayCollege.short : 'All'} Resources</h1>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12 }}>

        {/* ✅ FIX: safe map */}
        {Array.isArray(data) && data.map((r) => (
          <div key={r._id} style={{ border: '1px solid #ccc', padding: 10 }}>

            <h3>{r.title}</h3>

            <p>{r.subject}</p>

            {user?.role === 'teacher' && (
              <button onClick={() => handleDelete(r._id)}>
                Delete
              </button>
            )}

          </div>
        ))}

      </div>
    </div>
  );
}
